head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:     iNews 2014
Designer: Aumkar Thakur
URL:      www.seobloggertemplates.com
----------------------------------------------- */
/* Variable definitions
====================
<Group description="Theme Color">
<Variable name="theme.background.color" description="Choose Color" type="color" default="#4A7BF8" value="#4a7bf8"/>
</Group>
<Group description="Links" selector=".main-outer">
<Variable name="link.color" description="Link Color" type="color" default="#2288bb" value="#484545"/>
<Variable name="link.hover.color" description="Hover Color" type="color" default="#33aaff" value="#33aaff"/>
</Group>

*/

.list-label-widget-content ul li, .flus:hover, .lbls:hover, .Poplr:hover, .flus, .samazhlo, .scl-btn-sid, input.gsc-search-button, .ebtn, .breadcrumbs a, #comments .blog-author a


{
  background: $(theme.background.color);

}

a:link {
text-decoration:none;
  color: $(link.color);
}
a:hover {
text-decoration:underline;
  color: $(link.hover.color);
}
a:visited {  color: $(link.color);
}  

.navbar, .feed-links{display:none !important;}
#real-header{
width:900px;
margin:0 auto;
}
.real-header{box-shadow: 0px 1px 4px rgba(0,0,0,.2);
background:#fff;
border-bottom:1px solid #ddd;
position:fixed;
width:100%;
z-index:999999;
}
.header-outer .title{
  font-family: 'Open Sans';
  font-style: normal;
  font-weight: 300;
margin:-18px !important;
margin-lesft:20px !important;
font-size:32px;
}
header{
width:30% ;
float:left;
}
.menunav {
text-align: left;
display: inline;
margin: 0;
list-style: none;
position:relative;
z-index:99999999;
}
.menunav .firstli{
border-left:1px solid #ddd;
}
.menunav li {
border-right:1px solid #ddd;
margin-left:-4px;
font: 18px sans-serif;
display: inline-block;
position: relative;
padding: 15px 20px;
cursor: pointer;
-webkit-transition: all 0.2s;
-moz-transition: all 0.2s;
-ms-transition: all 0.2s;
-o-transition: all 0.2s;
transition: all 0.2s;
text-shadow:1px 1px 0 #fff;
}







.menunav  li:hover {
background: #ddd;
color: #fff;
}
.menunav  li ul {
padding: 0;
position: absolute;
top: 56px;
left: 0;
width: 160px;margin-left:3px;
-webkit-box-shadow: none;
-moz-box-shadow: none;
box-shadow: none;
display: none;
opacity: 0;
visibility: hidden;
-webkit-transiton: opacity 0.2s;
-moz-transition: opacity 0.2s;
-ms-transition: opacity 0.2s;
-o-transition: opacity 0.2s;
-transition: opacity 0.2s;
}
.menunav li ul li {
background: #eee;
display: block; z-index:999999999999;
color: #fff;
}
.menunav  li:hover ul {
display: block;
opacity: 1;
visibility: visible;
}
.menunav a{
text-decoration:none;
font-size:18px;color: #333333;
line-height: 26px;
  font-family: 'Open Sans';
  font-style: normal;
  font-weight: 400;
}
.main-outer {
background: #fff;
border: 1px solid #ddd;
width: 988px;
margin: 0 auto !important;
}
body{
background:#f9f9f9;
font-family: 'Open Sans';
font-style: normal;
font-weight: 400;
font-size:14px
}
.column-center-outer {
width: 65%;
float: left;
border-right:1px solid #ddd;
margin-top:-30px;
-webkit-box-shadow: 3px 0px 5px -2px #888;margin-bottom: -30px;

}
.column-right-outer {
width: 34%;
float: right;
}
.date-header, .post-footer{display:none;}
.post-title{
font-family: 'Open Sans';
font-style: normal;
font-weight: 300;
font-size:30px;
padding-bottom:10px;
}
.post-title a{
color:#000;
text-decoration:none;
}
.rmlink a{
background:#333;
color:white;
text-decoration:none;
padding:10px;

}
.post-outer{
border-bottom:1px solid #ddd;
padding-bottom:20px;
padding-top:20px;
margin-right:-30px;
margin-left:-30px;
padding-left:30px;
padding-right:30px;
}
.rthumbbox {
width: 200px;
margin-bottom: 20px;
border:1px solid #ddd;margin-right:25px;
