padding:10px;
  font-family: 'Lora';
  font-style: italic;
  font-weight: 400;
}
.firstka h2{
font-size:28px;
padding:20px;

}
.rthumbbox h2 a{
color:#000;
text-decoration:none;
}
.column-center-inner #main .HTML{display:none;
